-- ============================================================
-- FERIAS DE FIN DE SEMANA - LA PAZ (GRUPO 3)
-- Datos de prueba para PostgreSQL
-- Convertido de las 7 partes de inserts de Oracle (inserts_parte1 a 7).
-- Ejecutar DESPUES de 01_tablas_feria_postgres.sql
--
-- Cambios respecto a Oracle: se quitaron los bloques BEGIN ... COMMIT; END;
-- y todo va en una sola transaccion. Las fechas DATE 'AAAA-MM-DD' ya
-- eran validas en PostgreSQL.
-- ============================================================

SET client_encoding = 'UTF8';

BEGIN;

-- ---------- parte 1 ----------
-- LUGAR
-- FERIA
-- SE_EXPONE (FERIA - LUGAR)
-- ORGANIZADOR
-- PROMOTOR
-- ORGANIZA (ORGANIZADOR - FERIA/LUGAR)
-- PROMUEVE (PROMOTOR - FERIA/LUGAR)

-- ---------- parte 2 ----------
-- SECCION
-- PROPIETARIO
-- PRODUCTO

-- ---------- parte 3 ----------
-- PRODUCTO

-- ---------- parte 4 ----------
-- STAND (ENTIDAD DEBIL: PK = idSeccion + nro_stand)
-- VENDEDOR (GESTIONA: FK compuesta hacia STAND)

-- ---------- parte 5 ----------
-- VENDEDOR (GESTIONA: FK compuesta hacia STAND)

-- ---------- parte 6 ----------
-- VENDEDOR (GESTIONA: FK compuesta hacia STAND)
-- OFRECE (PRODUCTO - STAND)

-- ---------- parte 7 ----------
-- OFRECE (PRODUCTO - STAND)

COMMIT;

-- Verificacion: cantidad de filas por tabla
SELECT 'lugar' AS tabla, COUNT(*) AS filas FROM lugar
UNION ALL SELECT 'feria', COUNT(*) FROM feria
UNION ALL SELECT 'se_expone', COUNT(*) FROM se_expone
UNION ALL SELECT 'organizador', COUNT(*) FROM organizador
UNION ALL SELECT 'organiza', COUNT(*) FROM organiza
UNION ALL SELECT 'promotor', COUNT(*) FROM promotor
UNION ALL SELECT 'promueve', COUNT(*) FROM promueve
UNION ALL SELECT 'seccion', COUNT(*) FROM seccion
UNION ALL SELECT 'propietario', COUNT(*) FROM propietario
UNION ALL SELECT 'stand', COUNT(*) FROM stand
UNION ALL SELECT 'vendedor', COUNT(*) FROM vendedor
UNION ALL SELECT 'producto', COUNT(*) FROM producto
UNION ALL SELECT 'ofrece', COUNT(*) FROM ofrece;
